  // 9. unknown tool
  results.push(['unknown tool', await send({ jsonrpc: '2.0', id: 9, method: 'tools/call', params: { name: 'frobnicate', arguments: {} } })]);

  child.kill();
  rl.close();
  for (const [label, r] of results) console.log(label + ':', JSON.stringify(r));
